<?php

declare(strict_types=1);

namespace Mfonte\Base62x\Encryption\Cypher;

use Mfonte\Base62x\Exception\CryptException;

/**
 * @internal
 */
class Decrypt
{
    /**
     * Decrypts a token generated by Encrypt::token(), returning false on failure.
     *
     * @throws CryptException
     *
     * @return string|false
     */
    public static function token(string $data, string $method, string $key)
    {
        $ivHexLength = 2 * Bytes::iv($method);
        if (\strlen($data) <= $ivHexLength) {
            return false;
        }

        $iv = substr($data, 0, $ivHexLength);
        $encrypted = substr($data, $ivHexLength);
        if ($ivHexLength > 0 && !ctype_xdigit($iv)) {
            return false;
        }

        $binaryIv = $ivHexLength > 0 ? hex2bin($iv) : '';
        if ($binaryIv === false) {
            return false;
        }

        return openssl_decrypt($encrypted, $method, $key, 0, $binaryIv);
    }
}
